                double dki = l_data[k][i];
                corr_jj: for (int tj = 0; tj < TILE_J; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=tile_acc inter false
#pragma HLS DEPENDENCE variable=l_data inter false
