                norm_compute_j: for (int tj = 0; tj < TILE_J; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
#pragma HLS DEPENDENCE variable=tile_buf inter false
#pragma HLS DEPENDENCE variable=l_stddev inter false
