```cpp
#include "correlation.h"
#include <cmath>
#include <ap_int.h>
#include <string.h>

// Wide bus type: 512-bit = 8 x 64-bit doubles
#define LARGE_BUS 512
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;
#define DOUBLES_PER_WORD 8  // 512 / 64

// Tile sizes
#define TILE_J 16   // tile size along M (column) dimension
#define TILE_I 16   // tile size along N (row) dimension

// Unroll factor for inner loops
#define UNROLL_J 8

// Helper: read N_ELEM doubles from wide-bus array into a flat double array
// wide_arr: source ap_uint<512>* pointer
// dst: destination double* pointer
// n_elem: number of doubles to read
static void wide_bus_read_double(double* dst, const MARS_WIDE_BUS_TYPE* wide_arr, int n_elem) {
    int n_words = (n_elem + DOUBLES_PER_WORD - 1) / DOUBLES_PER_WORD;
    for (int w = 0; w < n_words; w++) {
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = wide_arr[w];
        for (int k = 0; k < DOUBLES_PER_WORD; k++) {
            int idx = w * DOUBLES_PER_WORD + k;
            if (idx < n_elem) {
                ap_uint<64> bits = word.range(64*k + 63, 64*k);
                double val;
                memcpy(&val, &bits, sizeof(double));
                dst[idx] = val;
            }
        }
    }
}

// Helper: write N_ELEM doubles from a flat double array into wide-bus array
static void wide_bus_write_double(MARS_WIDE_BUS_TYPE* wide_arr, const double* src, int n_elem) {
    int n_words = (n_elem + DOUBLES_PER_WORD - 1) / DOUBLES_PER_WORD;
    for (int w = 0; w < n_words; w++) {
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = 0;
        for (int k = 0; k < DOUBLES_PER_WORD; k++) {
            int idx = w * DOUBLES_PER_WORD + k;
            if (idx < n_elem) {
                double val = src[idx];
                ap_uint<64> bits;
                memcpy(&bits, &val, sizeof(double));
                word.range(64*k + 63, 64*k) = bits;
            }
        }
        wide_arr[w] = word;
    }
}

